// Run from the repository root: go run ./stage1/cohere/json/testdata/generate_shard_tests.go
// This generator uses only the Go standard library and never spawns child tools.
package main

import (
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

func main() {
	if err := generate(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func generate() error {
	for _, spec := range []struct{ directory, file, constants, count, name, helper string }{
		{"json", "top_portmatchesgocohere_test.go", "top_shared_test.go", "testPortMatchesGoCohereShards", "TestPortMatchesGoCohere", "jsonPortTopShard"},
		{"json", "top_upstreamrepositorycorpusparity_test.go", "top_shared_test.go", "testUpstreamRepositoryCorpusParityShards", "TestUpstreamRepositoryCorpusParity", "jsonUpstreamTopShard"},
		{"markdowninline", "shard_units_test.go", "shards_test.go", "testMarkdownInlineShards", "TestMarkdownInline", "runInlineUnit"},
	} {
		directory := filepath.Join("stage1", "cohere", spec.directory)
		source, err := os.ReadFile(filepath.Join(directory, spec.constants))
		if err != nil {
			return err
		}
		match := regexp.MustCompile(`(?m)^const ` + spec.count + ` = ([0-9]+)$`).FindSubmatch(source)
		if match == nil {
			return fmt.Errorf("missing literal shard count %s", spec.count)
		}
		count, err := strconv.Atoi(string(match[1]))
		if err != nil {
			return err
		}
		var out strings.Builder
		if spec.directory == "markdowninline" {
			existing, err := os.ReadFile(filepath.Join(directory, spec.file))
			if err != nil {
				return err
			}
			prefix, _, found := strings.Cut(string(existing), "func "+spec.name+"_0000(")
			if !found {
				return fmt.Errorf("missing generated block in %s", spec.file)
			}
			out.WriteString(prefix)
		} else {
			out.WriteString("// Code generated by testdata/generate_shard_tests.go; DO NOT EDIT.\npackage json\n\nimport \"testing\"\n\n")
		}
		for ordinal := 0; ordinal < count; ordinal++ {
			fmt.Fprintf(&out, "func %s_%04d(t *testing.T) { t.Parallel(); %s(t, %d) }\n", spec.name, ordinal, spec.helper, ordinal)
		}
		formatted, err := format.Source([]byte(out.String()))
		if err != nil {
			return err
		}
		if err := os.WriteFile(filepath.Join(directory, spec.file), formatted, 0644); err != nil {
			return err
		}
		fmt.Printf("generated %d parallel %s tests\n", count, spec.name)
	}
	return nil
}
